/** The day this build was made, YYYY-MM-DD (vite.config.ts). */
declare const __BUILD_DATE__: string;
/** Every service page's slug (vite.config.ts), so the main bundle needn't carry the pages. */
declare const __SERVICE_PAGE_SLUGS__: string[];

// Modules generated by the blog plugin in vite.config.ts from /content/blog.
declare module 'virtual:blog-routes' {
  /** Live post slugs, newest first. Small enough for the main bundle. */
  export const postSlugs: string[];
  export const categorySlugs: string[];
}

declare module 'virtual:blog-picks' {
  import type { BlogPostMeta } from './types';
  /** The three newest live posts, for the landing page. */
  export const latest: BlogPostMeta[];
  /** Up to three posts per service page slug, best match first. */
  export const guides: Record<string, BlogPostMeta[]>;
  /** The reading list on /offers/november. */
  export const novemberPosts: BlogPostMeta[];
}

declare module 'virtual:blog-index' {
  import type { BlogCategory, BlogPostBody, BlogPostMeta } from './types';
  /** Live posts, newest first. */
  export const posts: BlogPostMeta[];
  export const categories: BlogCategory[];
  /** One loader per post; each post's HTML is its own chunk. */
  export const loaders: Record<string, () => Promise<{ default: BlogPostBody }>>;
}
